section.script:
(function () {
  function loadScript(src, cb) {
    var s = document.createElement('script');
    s.src = src;
    s.onload = cb;
    s.onerror = cb;
    document.head.appendChild(s);
  }
  function announceReady() {
    document.dispatchEvent(new Event('sgc:gsap-ready'));
  }
  var fallbackTimer = setTimeout(announceReady, 5000);
  function onReady() {
    clearTimeout(fallbackTimer);
    announceReady();
  }
  if (window.gsap && window.ScrollTrigger) {
    onReady();
  } else if (window.gsap && !window.ScrollTrigger) {
    loadScript('/sgc_scroll_hero_v2/static/src/lib/ScrollTrigger.min.js', function () {
      if (window.ScrollTrigger) { onReady(); return; }
      loadScript('https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/ScrollTrigger.min.js', onReady);
    });
  } else {
    loadScript('/sgc_scroll_hero_v2/static/src/lib/gsap.min.js', function () {
      if (window.gsap) {
        loadScript('/sgc_scroll_hero_v2/static/src/lib/ScrollTrigger.min.js', function () {
          if (window.ScrollTrigger) { onReady(); return; }
          loadScript('https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/ScrollTrigger.min.js', onReady);
        });
        return;
      }
      loadScript('https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/gsap.min.js', function () {
        loadScript('https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/ScrollTrigger.min.js', onReady);
      });
    });
  }
  if (!document.querySelector('link[data-sgc-font="fraunces"]')) {
    var link = document.createElement('link');
    link.rel = 'stylesheet';
    link.setAttribute('data-sgc-font', 'fraunces');
    link.href = 'https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,600&display=swap';
    document.head.appendChild(link);
  }
})();
